import{_ as o,o as i,c as l,ag as a}from"./chunks/framework.D9kpkP22.js";const f=JSON.parse('{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"temp/COMMANDS.md","filePath":"temp/COMMANDS.md"}'),s={name:"temp/COMMANDS.md"};function t(d,e,c,r,n,m){return i(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><h2 id="player-commands" tabindex="-1">Player Commands <a class="header-anchor" href="#player-commands" aria-label="Permalink to &quot;Player Commands&quot;">​</a></h2><ul><li><p><code>/shop</code></p><ul><li>Opens the cosmetics shop GUI.</li><li>Permission: <code>frost.shop</code> (default: true)</li></ul></li><li><p><code>/equip</code></p><ul><li>Opens your equip menu to toggle owned cosmetics.</li><li>Permission: <code>frost.equip</code> (default: true)</li></ul></li><li><p><code>/togglelock</code></p><ul><li>Toggles Hotbar Lock on/off for your character and refreshes locked items when enabling.</li><li>Permission: none (player self‑service)</li></ul></li></ul><h2 id="admin-command" tabindex="-1">Admin Command <a class="header-anchor" href="#admin-command" aria-label="Permalink to &quot;Admin Command&quot;">​</a></h2><ul><li><p><code>/frost reload</code></p><ul><li>Reloads <code>config.yml</code>, profiles, and cosmetics from disk.</li><li>Permission: <code>frost.admin</code></li></ul></li><li><p><code>/frost setprofile &lt;player&gt; &lt;profile&gt;</code></p><ul><li>Sets a player’s active profile to one defined under <code>profiles</code> in <code>config.yml</code>.</li><li>Permission: <code>frost.admin</code></li></ul></li><li><p><code>/frost listprofiles</code></p><ul><li>Lists all available profile IDs and display names.</li><li>Permission: <code>frost.admin</code></li></ul></li><li><p><code>/frost givecosmetic &lt;player&gt; &lt;cosmetic&gt;</code></p><ul><li>Grants a cosmetic directly (bypasses economy), saving it to the player’s data.</li><li>Permission: <code>frost.admin</code></li></ul></li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li><code>frost.admin</code> – access to admin commands (default: op)</li><li><code>frost.shop</code> – can open the cosmetics shop (default: true)</li><li><code>frost.equip</code> – can open the equip menu (default: true)</li><li><code>frost.profile.&lt;profile-name&gt;</code> – gate access to specific profiles if you choose to enforce it</li></ul><p>Defined in <code>plugin.yml</code>. See also <a href="./CONFIGURATION.html">CONFIGURATION.md</a> for how profiles and cosmetics are declared.</p>',8)])])}const u=o(s,[["render",t]]);export{f as __pageData,u as default};
